import{_ as e,o as a,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Botão de cópia do número do processo em relatórios","description":"","frontmatter":{"title":"Botão de cópia do número do processo em relatórios","id":"eproc-copiar-cnj-relatorio","plataforma":"eproc","grupo":"Relatórios","plano":"free","desde":"1.5.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-copiar-cnj-relatorio"}]]},"headers":[],"relativePath":"funcionalidades/eproc-copiar-cnj-relatorio.md","filePath":"funcionalidades/eproc-copiar-cnj-relatorio.md"}'),t={name:"funcionalidades/eproc-copiar-cnj-relatorio.md"};function i(d,o,c,l,n,p){return a(),r("div",null,o[0]||(o[0]=[s('<h1 id="botao-de-copia-do-numero-do-processo-em-relatorios" tabindex="-1">Botão de cópia do número do processo em relatórios <a class="header-anchor" href="#botao-de-copia-do-numero-do-processo-em-relatorios" aria-label="Permalink to &quot;Botão de cópia do número do processo em relatórios&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Nas tabelas dos relatórios e das demais listagens do eproc, ao passar o mouse sobre um número de processo aparece um botão verde ao lado dele que copia o número com um clique.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, em qualquer tabela com números de processo: relatórios, pesquisas de processos (inclusive por nome da parte), área de trabalho de minutas e outras listagens.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Passe o mouse sobre o número de um processo numa tabela.</li><li>Clique no botão que aparece ao lado (&quot;Copiar número do processo&quot;).</li><li>Cole o número onde precisar.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Formato do número copiado</td><td>Com pontuação (0000000-00.0000.0.00.0000)</td><td>Também pode ser &quot;Somente dígitos&quot;.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O botão só aparece com o cursor sobre o próprio número e some assim que o cursor sai dele.</li><li>Se o navegador bloquear o acesso à área de transferência, o eploc usa um método alternativo de cópia.</li></ul>',11)]))}const h=e(t,[["render",i]]);export{m as __pageData,h as default};
